message.content:
{
  "outcome": "SUPPORTED",
  "claims": [
    {
      "text": "The initiative would provide AHV old-age pension recipients with an additional annual payment equal to one twelfth of their annual pension, described as a 13th pension payment.",
      "fact_ids": ["P01"]
    },
    {
      "text": "The initiative would increase annual AHV spending by approximately CHF 4.1 billion per year according to the government’s pre-vote estimate.",
      "fact_ids": ["P02"]
    }
  ],
  "unknowns": ["The exact additional personal financial burden on individual pensioners is not established by the evidence"]
}

{
  "outcome": "INSUFFICIENT_EVIDENCE",
  "claims": [
    {
      "text": "The evidence does not specify a definite additional personal CHF charge for employees.",
      "fact_ids": ["P04"]
    }
  ],
  "unknowns": ["The exact amount of any additional personal CHF charge on employees, if any, is not established in the provided evidence."]
}

{
  "outcome": "INSUFFICIENT_EVIDENCE",
  "claims": [
    {
      "text": "The initiative booklet does not specify that taxes must rise or spending must be cut; it leaves financing open.",
      "fact_ids": ["P04"]
    }
  ],
  "unknowns": ["Whether the Federal Council or Parliament later argued that taxes would need to rise or spending cut is not addressed in the supplied evidence"]
}

{
  "outcome": "INSUFFICIENT_EVIDENCE",
  "claims": [
    {
      "text": "The initiative proposes an annual supplement equal to one twelfth of the annual pension for AHV old-age pension recipients, described as a 13th pension payment.",
      "fact_ids": ["P01"]
    },
    {
      "text": "The government projects the initiative would add approximately CHF 4.1 billion per year to AHV spending upon introduction, rising to around CHF 5 billion five years later.",
      "fact_ids": ["P02", "P03"]
    }
  ],
  "unknowns": ["The specific additional personal charge to taxpayers or the exact financing method, as the initiative left financing open and the booklet does not establish a definite additional personal CHF charge."]
}

{
  "outcome": "INSUFFICIENT_EVIDENCE",
  "claims": [],
  "unknowns": ["The evidence does not contain any information about events after the vote in 2026"]
}
